/**
 * Generic transport for Enkaku RPC clients and servers.
 *
 * ## Installation
 *
 * ```sh
 * npm install @enkaku/transport
 * ```
 *
 * @module transport
 */ import { Disposer } from '@enkaku/async';
import { EventEmitter } from '@enkaku/event';
import { createConnection, writeTo } from '@enkaku/stream';
/**
 * Base Transport class implementing TransportType.
 */ export class Transport extends Disposer {
    #events;
    #params;
    /** @internal */ _reader;
    /** @internal */ _stream;
    /** @internal */ _writer;
    constructor(params){
        super({
            dispose: async ()=>{
                if (this._stream != null) {
                    const writer = await this._getWriter();
                    try {
                        await writer.close();
                    } catch  {
                    // Ignore error closing writer in case it's already closed
                    }
                }
            }
        });
        this.#events = new EventEmitter();
        this.#params = params;
    }
    get events() {
        return this.#events;
    }
    /** @internal */ _getStream() {
        if (this._stream == null) {
            const { stream } = this.#params;
            this._stream = Promise.resolve(typeof stream === 'function' ? stream() : stream);
        }
        return this._stream;
    }
    /** @internal */ _getReader() {
        if (this._reader == null) {
            this._reader = this._getStream().then(({ readable })=>{
                return readable.getReader();
            });
        }
        return this._reader;
    }
    /** @internal */ _getWriter() {
        if (this._writer == null) {
            this._writer = this._getStream().then(({ writable })=>{
                return writable.getWriter();
            });
        }
        return this._writer;
    }
    getWritable() {
        return writeTo(async (value)=>await this.write(value));
    }
    async read() {
        const reader = await this._getReader();
        return await reader.read();
    }
    async write(value) {
        const writer = await this._getWriter();
        await writer.write(value);
    }
    [Symbol.asyncIterator]() {
        return {
            next: async ()=>{
                const next = await this.read();
                return next.done ? {
                    done: true,
                    value: next.value ?? null
                } : next;
            }
        };
    }
}
/**
 * Create direct Transports for communication between a client and server in the same process.
 */ export class DirectTransports extends Disposer {
    #client;
    #server;
    constructor(options = {}){
        super({
            ...options,
            dispose: async (reason)=>{
                await Promise.all([
                    this.#client.dispose(reason),
                    this.#server.dispose(reason)
                ]);
            }
        });
        const [serverStream, clientStream] = createConnection();
        this.#client = new Transport({
            stream: clientStream
        });
        this.#server = new Transport({
            stream: serverStream
        });
    }
    get client() {
        return this.#client;
    }
    get server() {
        return this.#server;
    }
}
